-- PDCA Hub · Visitas técnicas (/dashboard/projetos/visitas): "?" dos indicadores, da busca, do filtro, do próximo passo e
-- das ações (RD-95). Aditiva (só texto de ajuda; nenhum dado de cliente tocado).
INSERT INTO public.erp_ajuda_campo (chave, grupo, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum, ordem, rota, vertical, status)
SELECT v.chave, 'Visitas técnicas', v.rotulo, v.o_que, v.para_que, v.exemplo, v.erro, v.ordem, '/dashboard/projetos/visitas', 'hub_construcao', 'publicado'
FROM (VALUES
 ('projetos.visitas.nova', 'Nova visita', 'Clique para agendar ou registrar uma visita: escolha o cliente, a data, o responsável e o endereço da obra.', 'A visita é o primeiro passo do funil: com ela registrada, a oportunidade anda para "visita feita" e o orçamento sai com as medidas e fotos de campo.', 'Visita amanhã às 9h na casa do Sr. João, rua das Flores 120, com o vendedor Carlos.', 'Registrar a visita sem cliente: a visita fica solta e não entra no funil.', 1),
 ('projetos.visitas.ind_proximas', 'Próximos 7 dias', 'Nada a preencher: conta as visitas agendadas de hoje até daqui a 7 dias.', 'Mostra a agenda de campo da semana. Clique no número para ver só essas visitas na lista.', '3: duas visitas na quarta e uma na sexta.', 'Achar que inclui as atrasadas: visita com data que já passou aparece no indicador "Passaram da data".', 2),
 ('projetos.visitas.ind_atrasadas', 'Passaram da data', 'Nada a preencher: conta as visitas ainda "agendadas" cuja data já passou.', 'Aponta visita esquecida: ou foi feita e falta marcar "realizada", ou precisa ser reagendada. Clique no número para ver quais são.', '1: a visita de segunda continua agendada.', 'Deixar a visita feita como "agendada": o funil não anda e o orçamento não é cobrado.', 3),
 ('projetos.visitas.ind_realizadas_mes', 'Realizadas no mês', 'Nada a preencher: conta as visitas marcadas como "realizada" com data no mês atual.', 'Mede o ritmo de campo da equipe no mês. Clique no número para ver a lista.', '8 visitas realizadas em outubro.', 'Contar visita cancelada: cancelada não entra neste número.', 4),
 ('projetos.visitas.ind_sem_orcamento', 'Realizadas sem orçamento', 'Nada a preencher: conta as visitas realizadas que ainda não têm orçamento (nem gerado na visita nem na oportunidade).', 'É o dinheiro parado: cliente visitado esperando proposta. Clique no número, abra a oportunidade e gere o orçamento.', '2 visitas feitas na semana passada ainda sem orçamento.', 'Gerar o orçamento fora da oportunidade: aí a visita continua contando aqui.', 5),
 ('projetos.visitas.busca', 'Buscar visitas', 'Digite parte do nome do cliente, do título da oportunidade, do endereço ou do responsável.', 'Encontra a visita rápido na lista, junto com o filtro de status e o indicador escolhido.', '"flores" acha a visita da rua das Flores.', 'Buscar com o recorte de um indicador ligado: limpe o recorte para buscar em todas.', 6),
 ('projetos.visitas.filtro_status', 'Status da visita', 'Escolha Todas, Agendada, Realizada ou Cancelada para ver só as visitas nesse status.', 'Separa a agenda (agendadas) do que já foi feito (realizadas).', 'Realizada: mostra só as visitas que já aconteceram.', 'Esquecer o filtro ligado e achar que a visita sumiu: volte para "Todas".', 7),
 ('projetos.visitas.proximo_passo', 'Próximo passo', 'Nada a preencher: o sistema mostra o que fazer agora com base no status, na data e no orçamento da visita.', 'Guia o vendedor: ir à visita, marcar como realizada, gerar o orçamento ou acompanhar a proposta.', '"Gerar o orçamento na oportunidade" numa visita realizada sem orçamento.', 'Ignorar "Passou da data": a visita fica parada e some do funil.', 8),
 ('projetos.visitas.acoes', 'Ações da visita', 'Editar muda data, status, responsável, fotos e anotações. Abrir oportunidade leva à ficha, onde se gera o orçamento. Abrir orçamento mostra a proposta já criada.', 'Fecha o ciclo visita → orçamento sem procurar em outra tela.', 'Visita realizada: clique em "Gerar orçamento na oportunidade".', 'Criar um orçamento avulso em vez de gerar pela oportunidade: o vínculo com a visita se perde.', 9)
) AS v(chave, rotulo, o_que, para_que, exemplo, erro, ordem)
WHERE EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'erp_ajuda_campo')
ON CONFLICT (chave) DO NOTHING;
